import{_ as a}from"./chunks/7575f8a7a515075b636e.AoMMcZPm.js";import{_ as r,C as o,o as l,c as n,j as p,a as i,E as s,a6 as h}from"./chunks/framework.CnPv4DE1.js";const w=JSON.parse('{"title":"改变我人生的深度工作安排","description":"","frontmatter":{"title":"改变我人生的深度工作安排","originalTitle":"The Deep Work Routine That Changed My Life","date":"2025-05-08","originalUrl":"https://thedankoe.com/letters/the-deep-work-routine-that-changed-my-life/","minutes":9,"sourceHash":"0c39397bfd81762c9b3cd6bcca3f023ac5fd9393fcc8caba4d39b0af2bec5d79","translation":"AI-assisted, block-aligned; not official","head":[["link",{"rel":"canonical","href":"https://thedankoe.com/letters/the-deep-work-routine-that-changed-my-life/"}]]},"headers":[],"relativePath":"letters/the-deep-work-routine-that-changed-my-life.md","filePath":"letters/the-deep-work-routine-that-changed-my-life.md"}'),c={name:"letters/the-deep-work-routine-that-changed-my-life.md"};function d(m,e,f,g,u,k){const t=o("ArticleMeta");return l(),n("div",null,[e[0]||(e[0]=p("h1",{id:"改变我人生的深度工作安排",tabindex:"-1"},[i("改变我人生的深度工作安排 "),p("a",{class:"header-anchor",href:"#改变我人生的深度工作安排","aria-label":'Permalink to "改变我人生的深度工作安排"'},"​")],-1)),s(t),e[1]||(e[1]=h('<p><a href="https://www.youtube.com/embed/kLd5AvsLWAc?feature=oembed" target="_blank" rel="noreferrer">观看原文视频</a></p><p>每天至少留出1小时。</p><p>专注做1个有意义的项目。</p><p>为你的未来瞄准1个愿景。</p><p>一天一天地推进。</p><p>你不需要更多动力,你需要更多清晰。</p><p>你不需要更多时间,你需要更多专注。</p><p>如果你想要更多这两者,理解这一点:</p><p>你的大脑是一台超级计算机。</p><p>你的注意力就是RAM。</p><p>RAM——也就是“随机存取存储器”——是电脑最重要的部件之一,它决定了性能。</p><p>打开更多程序和浏览器标签页=性能变慢。</p><p>这和你的专注力没什么不同。</p><p>人类的意识注意力大约每秒能处理50比特的信息(相比之下,我们从已学会的技能中无意识处理的信息量是1100万比特)。</p><p>这累积起来,一生中大约是1250亿比特的意识信息。</p><p>那就是你的定时炸弹。</p><p>你要么把这1250亿比特投资到更好的未来中,要么就让分心像电脑上的浏览器标签页一样把它们堵塞起来。</p><p>对大多数人来说,在普通的一天里,那份宝贵的专注力在以下事情之间混乱地跳跃:</p><ul><li>关于充满压力的未来、无聊的当下、以及令人后悔的过去的想法</li><li>一种想要打破他们被条件化的生活方式的内心呼喊</li><li>一份优先级混乱、需要完成的任务清单</li></ul><p>这样的清单还可以列很长。</p><p>现代人的大脑,在他们早上一打开手机的那一刻,注意力就被拆成了一千个不同的方向。</p><h2 id="在熵值低的时候-做你最好的工作" tabindex="-1">在熵值低的时候,做你最好的工作 <a class="header-anchor" href="#在熵值低的时候-做你最好的工作" aria-label="Permalink to &quot;在熵值低的时候,做你最好的工作&quot;">​</a></h2><p>在我们继续之前,我想让你原谅我。</p><p>这个“改变我人生的深度工作日程”并没有什么革命性的东西。</p><p>它其实相当简单。</p><p>我试过所有的效率技巧。工作时段计时器。甚至戴帽子来模拟视野收窄、屏蔽干扰。</p><p>就像你最喜欢的Notion模板一样,最终,所有系统都会崩坍,或者演变以适应你新出现的需求。</p><p>这就是为什么我想专注于那些能帮助任何人在4小时内完成8小时工作量的核心原则。</p><p>要理解第一个原则,你必须理解熵。</p><p>你必须明白,对你的人生什么都不做,就是选择慢慢淹没在混乱之中。</p><p>你不会保持原样。</p><p>你会在毫不努力的情况下,把自己越陷越深。</p><p>因为美好的人生要求你为自己的目标持续付出<em>努力</em>。</p><p>不把它搞得太复杂,熵就是衡量一个事物有多混乱、无序或随机的指标。</p><p>热力学第二定律,简而言之,指出在任何自然过程中,总熵(或无序度)会随时间趋于增加,除非有努力(或能量)投入去维持系统的有序。</p><p>如果你不花力气维护你的书架,书就会散落在你家各处、你朋友家里,小范围的混乱就会随之而来。</p><p>如果你不花力气打扫房间,它会慢慢变得越来越脏,直到你活在一个令人作呕的污秽窝里。</p><p>现在,想象同样的过程,但施加在你的大脑上。</p><p>或者文化、政治、经济市场,或者其他任何东西。</p><p>但我想专注于<em>心理熵</em>。</p><p>也就是你的大脑趋向无序的过程。</p><p>如果你不打扫你的心理房间——大多数人都不打扫——它就会变成一个令人作呕的小巨怪洞穴,你妈妈每隔一天就冲你喊叫要你打扫。</p><p>这引出了几个要点:</p><h3 id="_1-你没有效率-是因为你缺乏清晰" tabindex="-1">1)你没有效率,是因为你缺乏清晰 <a class="header-anchor" href="#_1-你没有效率-是因为你缺乏清晰" aria-label="Permalink to &quot;1)你没有效率,是因为你缺乏清晰&quot;">​</a></h3><p>这可能看起来很显而易见。</p><p>你没有效率,是因为你专注于某个分心之事,不去纠正自己,慢慢被你允许进入脑中的混乱所淹没。</p><p>分心是熵的起点,因为它们把努力/能量从你的目标上转移开。</p><p>有两种方法可以识别分心并纠正自己:</p><p><strong>无聊和焦虑。</strong></p><p>如果你正在完成的任务的挑战性对你的技能水平来说太低,你会感到无聊。</p><p>如果你正在完成的任务的挑战性对你的技能水平来说太高,你会感到焦虑。</p><p><strong>无聊</strong>源于以自我为中心。</p><p>你的专注力破裂,一个新的欲望在你脑中冒出,相关的想法开始填满你的注意力。</p><p>如果你对这个任务感到无聊,你会开始想还有什么更好的事情可以做。</p><p><strong>焦虑</strong>源于自我意识过强。</p><p>你的注意力转向内部,负面想法涌入你的脑中,关于你还不够好的念头。</p><p>如果你照镜子发现一颗痘,那可能会揭示出你外表上更多的瑕疵,进而想到要养成健身习惯、吃更健康的食物,慢慢地你的大脑就被占据了。</p><p>由无聊或焦虑引发的混乱,唯有用清晰才能治愈。</p><p>你必须重新聚焦你的大脑,不仅聚焦于眼前的任务,还要聚焦于你整个人生的理想结果。</p><p>当你的技能和知识与任务的挑战相匹配时,人生就变成了一场你喜欢玩的任务型电子游戏。</p><hr><p>如果你不知道你理想的人生是什么样子,可以试着运行一下<a href="https://kortex.co/" target="_blank" rel="noreferrer">Kortex中的Life Reset Map工作流</a>。它会通过关键问题采访你,了解你的处境、技能和兴趣,然后为你吐出你理想生活的第一版迭代,包括你的愿景、技能发展树、长短期目标等等。</p><p><img src="'+a+'" alt=""></p><p>只需前往 Chat &gt; Plan &gt; Life Reset Map</p><hr><h3 id="_2-把你的工作时段当作电子游戏里的任务来对待" tabindex="-1">2)把你的工作时段当作电子游戏里的任务来对待 <a class="header-anchor" href="#_2-把你的工作时段当作电子游戏里的任务来对待" aria-label="Permalink to &quot;2)把你的工作时段当作电子游戏里的任务来对待&quot;">​</a></h3><blockquote><p>内在体验的最佳状态,是意识中存在秩序的那种状态。这发生在心理能量——即注意力——被投入到现实的目标中,并且技能与行动机会相匹配的时候。追求一个目标会在意识中带来秩序,因为一个人必须把注意力集中在眼前的任务上,暂时忘记其他一切。</p><p>——米哈里·契克森米哈赖(Mihaly Csikszentmihalyi)</p></blockquote><p>电子游戏令人上瘾有几个原因:</p><ul><li><strong>存在一个清晰的目标层级</strong>,挑战难度不断递增,要求技能不断提升(你知道如何获胜,并在这过程中成为某个人)</li><li><strong>存在规则和反馈循环</strong>,让你的注意力保持在游戏之内,并最小化分心(你专注于令人愉悦的进展)</li></ul><p>上周,我们谈到了如何<a href="https://thedankoe.substack.com/p/how-to-launch-into-a-completely-new" target="_blank" rel="noreferrer">将这个框架应用到彻底改变你的整个人生</a>,而不仅仅是你的深度工作时段。</p><p>你可以把你的人生想象成整场游戏,深度工作时段就是这场游戏中的任务,完成之后会带来经验值和特质发展。</p><p>在我看来,实现这一点最简单的方法就是以下几点:</p><p><strong>1)量化你的2-3个“最重要的任务”</strong></p><p>这不意味着你一天只做2-3件事。</p><p>我们很快会讲到那部分。</p><p>现在,你的<em>最重要的任务</em>是那些需要最多脑力能量的任务。深度工作是给深度任务用的。浅层工作是给像邮件、行政事务之类的事情用的,这些可以打包在一起,在专注力高峰期之外完成。</p><p>你最重要的任务,是维护性事务的反面。</p><p><em>它们最能把指针推向你正在努力建立的人生。</em></p><p><em>这些是如果不完成,就会导致你停滞不前或倒退的任务。</em></p><p>比如在你早上上班之前,建立一个能给你带来更多时间和财务自由的有意义项目。</p><p>或者,对创作者来说,它可能是打造一个新产品、写推广文案,或者拉动那些带来分发和销售的杠杆。</p><p>如果可以,量化这些任务。</p><p>不要说“写一点我的newsletter”,而要说“写1000字”。</p><p>这会创造一个反馈循环。你能<em>看到</em>自己正在取得的进展,这能防止你的大脑离开这个任务。</p><p><strong>2)设定一个有挑战性的截止时间,并附带一个必须遵守它的重要理由</strong></p><blockquote><p><em>你是谁,你想什么、感受什么、做什么,你爱什么——都是你所关注事物的总和。——卡尔·纽波特(Cal Newport)</em></p></blockquote><p>我们的大脑每天进行深度、专注工作的能力是有限的。</p><p>把你的首要任务限制在2-3个,会强迫你对什么才真正重要变得毫不留情,并让你与更大的目标保持一致。</p><p>这是收窄专注、把分心挡在门外的第一层级。</p><p>第二层级,要进一步收窄,就是通过为每个任务设置时间块的形式来创造一个截止期限。</p><p>这没什么新鲜的。我们都知道截止期限能如何逼哪怕是拖延症患者也切入心流状态,在最后一刻把所有工作都做完。但你可以每天早晨复制这个过程,让你在下个月取得的进展比过去一年都多。</p><p>我喜欢用两种方法来确保截止期限的存在:</p><ol><li>在有挑战性的时间块内工作。通常是60-90分钟。</li><li>在时间块之间安排一件重要的、与工作无关的任务。</li></ol><p>如果我要为我的newsletter写1000字,我会给自己60分钟去做这件事。</p><p>这通常时间不够,但这是有原因的:我没有时间去想该写什么。我只需要写,因为时钟正在滴答走动。而如果我没写完,那更好,因为这会激发蔡加尼克效应(Zeigarnik Effect,你的大脑想要完成未闭合的循环),这会让我更容易在下一个时间块里重新进入深度工作状态。</p><p>在工作时间块之间,我会加入一些需要完成的小任务,比如吃早餐,因为如果我不吃,我一天中稍后的健身时段就会受到影响,而我的健康对我来说极其重要。</p><p>如果你不重视你的健康、人际关系,或者人生的其他方面,你的效率就会受损,因为你没有理由去<em>停止</em>工作,这会导致工作缺乏专注。</p><p>大多数拼命干活、一天分心地工作16个小时的人(即使他们以为自己很专注),都无法理解:只要有一份负责任、有优先级的生活,你在4-6小时内就能完成更有效的工作。</p><h3 id="_3-优先照顾心理代谢" tabindex="-1">3)优先照顾心理代谢 <a class="header-anchor" href="#_3-优先照顾心理代谢" aria-label="Permalink to &quot;3)优先照顾心理代谢&quot;">​</a></h3><p>到目前为止,我的深度工作日程是这样的:</p><ul><li><strong>把时间块从低熵排到高熵</strong>——世界在一天最开始的时候是安静的。没有邮件。没有和别人的沟通。没有手机。没有任何能让你的大脑陷入混乱、悄悄影响你工作的东西。</li><li><strong>在2-3个时间块里完成2-3个最重要的任务</strong>——每个时间块里是否完成1个任务并不重要,只要你能感受到那种收窄专注的时间块所带来的压力就行。</li><li><strong>只有深度工作完成后,才做浅层工作</strong>——不要,我再说一遍,不要在深度工作完成之前查看邮件、社交媒体或其他任何东西。你可以去发个帖子,但前提是你发完就离开,回去继续工作。</li></ul><p>那一天剩下的时间怎么办呢?</p><p>好吧,如果你把你的大脑想象成你的身体,你刚刚花了几个小时在心理健身房里训练到力竭。你消耗了95%的心理能量,需要进食、恢复,做一切必要的事,好让自己明天以最佳状态出现。</p><p>在我这里,我的大部分工作取决于我想法和策略的质量。</p><p>有了这一点,我大部分的“工作”其实是在我真正开始工作之前就完成了。</p><p>当我一坐下开始的时候,我对该做什么有绝对的清晰,因为我一天的后半段都花在了休闲最大化上。</p><p>我用富有营养的食物填满我的大脑。</p><p>我给心智做碳水填充,让它能发挥最佳状态。</p><p>我会去散步、读书、和聪明的人交谈、和我爱的人一起放松，并尝试每周至少学习或做几件新事情。新的地方、新的体验、新的趋势或技能。能让我保持新鲜感的东西。</p><p>最后总结一下：</p><p>要明白，作为一个创作者，在迈向未来工作方式的过程中，那些“工作”最少的人最终会站在顶端，因为当AI几乎能做任何事情时，你的故事、你对想法的综合能力，以及你的经验，才是唯一的护城河。</p><p>感谢阅读。</p><p>——Dan</p><hr><p>当你准备好时，以下是我可以进一步帮助你的几种方式：</p><ul><li>最新的付费文章是一个<a href="https://substack.com/@thedankoe/note/p-163073465" target="_blank" rel="noreferrer">你可以在每次深度工作开始前使用的AI提示词</a>，用来规划你的优先任务，并引导你进入心流状态。</li><li>每周六，我会向我个人邮件列表上的175,000多人发送一份高信号密度的写作摘要。如果你想收到它，<a href="https://thedankoe.com/letters" target="_blank" rel="noreferrer">可以在这里加入。</a></li><li>如果你想把所有AI模型集中在一个地方，能够快速引用文档和PDF文件，并使用25个以上预构建的工作流来进行学习、写作、营销和规划——<a href="https://kortex.co/" target="_blank" rel="noreferrer">在这里免费注册Kortex。</a></li></ul><hr><p><a href="/en/letters/the-deep-work-routine-that-changed-my-life">查看英文存档</a> · <a href="/letters/">返回全部文章</a></p>',118))])}const x=r(c,[["render",d]]);export{w as __pageData,x as default};
